using LantanaGroup.Link.Automation; using LantanaGroup.Link.Automation.Configuration; using LantanaGroup.Link.Automation.Helpers; using LantanaGroup.Link.Automation.Services; using LantanaGroup.Link.Automation.Validation; using RestSharp; using Xunit; using Task = System.Threading.Tasks.Task;  namespace LantanaGroup.Link.Tests.E2ETests;  /// <summary> /// End-to-end smoke test that runs a single generated patient through the full /// ad-hoc reporting pipeline. /// </summary> public sealed class SmokeTest : IAsyncLifetime {     private const string FacilityId = "SmokeTestFacility";      private static readonly AutomationConfig AutomationCfg = TestConfig.BuildAutomationConfig();     private static readonly TestScenarioConfig Config = TestConfig.AdhocReportingSmokeTestConfig;     private static readonly FhirDataLoader FhirDataLoader = new(AutomationCfg.ExternalFhirServerBase, AutomationCfg);     private static readonly DatabaseConnectionFactory DbFactory = new(AutomationCfg.Database);      private readonly DualOutputHelper _output;     private readonly RestClient _adminBffClient = AdminBffClientFactory.Create(AutomationCfg);     private readonly LokiScraper _lokiScraper;      private FacilityApiClient FacilityApi => new(_adminBffClient, _output);     private NormalizationApiClient NormalizationApi => new(_adminBffClient, _output);     private QueryConfigApiClient QueryConfigApi => new(_adminBffClient, _output, AutomationCfg);     private ReportApiClient ReportApi => new(_adminBffClient, _output, _lokiScraper, AutomationCfg, Config);     private ValidationApiClient ValidationApi => new(_adminBffClient, _output, _lokiScraper);      public SmokeTest()     {         _output = new DualOutputHelper();         _lokiScraper = new LokiScraper(_output, AutomationCfg);     }      public async Task InitializeAsync()     {         // Generate a small synthetic patient dataset for smoke validation.         var (patientIds, bundles) = FhirBundleGenerator.Generate(_output, 1, 3000, "SmokePatient");          // If config does not explicitly provide IDs, use generated IDs.         if (Config.PatientIds.Count == 0)         {             Config.PatientIds = patientIds;         }          _output.WriteLine($"Patient IDs for test: [{string.Join(", ", Config.PatientIds)}]");          // Wait for FHIR readiness before uploading data.         await FhirDataLoader.WaitForServerAsync(_output);          // Load generated FHIR bundles.         await FhirDataLoader.LoadTransactionBundlesFromJsonAsync(_output, bundles);          // Initialize validation services.         await ValidationApi.InitializeArtifactsAsync();         await ValidationApi.InitializeCategoriesAsync();     }      public async Task DisposeAsync()     {         _output.WriteLine("Cleaning up...\n");          if (Config.RemoveFacilityConfig)         {             await FacilityApi.DeleteAsync(FacilityId);         }          if (AutomationCfg.CleanupTestData)         {             FhirDataLoader.ExpungeEverything(_output);         }          if (Config.RemoveReport)         {             // TODO: Delete report         }     }      [Fact]     [Trait("Category", "SmokeTest")]     public async Task ExecuteSmokeTest()     {         // Step 1: Load measure definition into MeasureEval and Validation.         var measureLoader = new MeasureLoader(_adminBffClient, _output, Config);         await measureLoader.LoadAsync();          var measureId = measureLoader.MeasureId             ?? throw new InvalidOperationException("MeasureLoader did not produce a MeasureId");          // Step 2: Create facility.         await FacilityApi.CreateAsync(FacilityId, measureId);          // Step 3: Create normalization config.         await NormalizationApi.CreateConfigAsync(FacilityId);          // Step 4: Create query plans (Discharge + Monthly).         await QueryConfigApi.CreateQueryPlanAsync(FacilityId, measureId, "Epic");          // Step 5: Create FHIR query config.         await QueryConfigApi.CreateQueryConfigAsync(FacilityId);          // Step 6: Generate the ad-hoc report.         var reportId = await ReportApi.GenerateReportAsync(FacilityId, measureId);          // Step 7: Start background diagnostics and poll until submitted.         await using var diagnostics = new BackgroundDiagnosticsMonitor(_output, _lokiScraper, AutomationCfg, Config.PatientIds.Count);         await diagnostics.StartAsync(FacilityId, reportId);          var reportSubmitted = await ReportApi.CheckSubmissionStatusAsync(reportId, diagnostics);         await diagnostics.StopAsync();          // Always capture a non-asserting snapshot before assertions.         var pipelineSnapshot = new PipelineSnapshot(DbFactory);         await pipelineSnapshot.WriteFullSnapshotAsync(_output, FacilityId, reportId);          Assert.True(reportSubmitted,             $"Expected report with id {reportId} to be submitted but it was not. " +             $"Check [DIAG] and [Snapshot] output above for root cause details.");          // Step 8: Download and validate report artifacts.         var downloadedResources = await ReportApi.DownloadReportAsync(FacilityId, reportId);          Assert.True(downloadedResources.ContainsKey("manifest.ndjson"),             "Expected report to include manifest.ndjson but it was not");          foreach (var patientId in Config.PatientIds)         {             Assert.True(downloadedResources.ContainsKey($"patient-{patientId}.ndjson"),                 $"Expected report to include patient-{patientId}.ndjson but it was not");         }          _output.WriteLine("Done generating and validating report.");          // Step 9-10: Strict database validation.         var reportDbValidator = new ReportDatabaseValidator(_output, DbFactory);         await reportDbValidator.ValidateAllAsync(FacilityId, reportId, measureId, Config.PatientIds);          var dataAcqValidator = new DataAcquisitionDatabaseValidator(_output, DbFactory);         await dataAcqValidator.ValidateAllAsync(FacilityId, reportId, measureId, Config.PatientIds);          var normalizationValidator = new NormalizationDatabaseValidator(_output, DbFactory);         await normalizationValidator.ValidateAllAsync(FacilityId);          var tenantValidator = new TenantDatabaseValidator(_output, DbFactory);         await tenantValidator.ValidateAllAsync(FacilityId, measureId);          // Step 11: Validation results API verification.         var validationResultsValidator = new ValidationResultsValidator(_adminBffClient, _output);         await validationResultsValidator.ValidateAllAsync(FacilityId, reportId, Config.PatientIds);     } }  